contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // We will attempt withdraw and withdrawAll from this contract (which is NOT the owner of c)
    // Provide amounts and an initial funding amount to send to c via its fallback (by sending raw ether to c)
    function run(uint sendToC, uint withdrawAmount) public payable {
        require(address(this).balance >= sendToC, "insufficient balance to fund c");
        // record balance of c before funding
        uint beforeBalance = address(c).balance;
        // fund c by sending Ether to its fallback
        // Use call to trigger fallback; since fallback is payable it increments depositsCount and balance
        (bool s,) = address(c).call{value: sendToC}("\x00");
        // ensure the funding call succeeded
        require(s, "funding c failed");
        uint afterFundBalance = address(c).balance;
        // afterFundBalance should equal beforeBalance + sendToC
        require(afterFundBalance == beforeBalance + sendToC, "unexpected fund change");

        // Now attempt to call withdraw and withdrawAll from this (non-owner) contract and catch reverts
        bool withdrewReverted;
        try c.withdraw(withdrawAmount) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        bool withdrawAllReverted;
        try c.withdrawAll() {
            withdrawAllReverted = false;
        } catch {
            withdrawAllReverted = true;
        }

        uint finalBalance = address(c).balance;

        // General rule: since this contract is not the owner, both withdraw and withdrawAll must revert,
        // and c's balance must remain equal to afterFundBalance (no funds can be taken by non-owner).
        assert(withdrewReverted && withdrawAllReverted && finalBalance == afterFundBalance);
    }

    receive() external payable {}
}

