contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // This contract is NOT the owner of c (owner is deployer of C).
    // Parameters: amount to fund C so it has balance, and an amount to attempt to withdraw.
    function run(uint fundAmount, uint tryWithdraw) public payable {
        require(address(this).balance >= fundAmount, "insufficient balance to fund c");
        // Fund c by calling its fallback (payable). Use a plain low-level call to trigger fallback behavior.
        (bool ok, ) = address(c).call{value: fundAmount}("\x00");
        require(ok, "funding c failed");

        // Record balance after funding
        uint before = address(c).balance;

        // Attempt withdraw from this contract (which is not the owner). Must be a top-level try/catch on c.withdraw.
        bool reverted;
        try c.withdraw(tryWithdraw) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint after = address(c).balance;

        // General rule: since this contract is not the owner, the withdraw call must revert and C's balance must remain unchanged.
        assert(reverted && after == before);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    address deployer;
    constructor(C _c) { c = _c; deployer = address(this); }
    // single public entry performing the property-based test
    function run(address caller, uint sendAmount, uint withdrawAmount, bytes calldata data) public payable {
        require(true);
        // Ensure this contract has enough balance to send to C if needed
        if (sendAmount > 0) {
            require(address(this).balance >= sendAmount);
            // send Ether to C via fallback by calling with empty data
            (bool s, ) = address(c).call{value: sendAmount}(new bytes(0));
            // fallback increments depositsCount on successful payable call; require not to revert here
            // but we won't require s; we just proceed and observe state
            s; 
        }

        // record state before attempted withdraw by a non-owner (caller param)
        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount();

        // Simulate a call from 'caller' by using low-level call: the InvMutTest is the sender in reality,
        // but we can forward the calldata to c via call on c using encoded selector of withdraw
        // to emulate arbitrary caller we must assert that only owner can succeed; since this contract is owner,
        // we check behavior when attempting to invoke withdraw as if the target were a different address by
        // calling c.sendMoney to forward a call from C to itself — instead we instead check that external callers
        // (not owner) cannot change c state by directly calling withdraw through a forwarded call that sets msg.sender!=owner.
        // Achieve this by asking C to call its own withdraw via sendMoney with target = address(c) and data encoding withdraw(uint)

        // prepare calldata for withdraw(uint)
        bytes memory withdrawCalldata = abi.encodeWithSignature("withdraw(uint256)", withdrawAmount);

        // Attempt: have C call itself (so msg.sender inside withdraw will be C, not owner) by using sendMoney.
        // Only owner can call sendMoney; since this contract is owner (deployer), this will execute and attempt to call withdraw
        bool sendMoneyReverted;
        try c.sendMoney(address(c), 0, withdrawCalldata) {
            sendMoneyReverted = false;
        } catch {
            sendMoneyReverted = true;
        }

        // After the attempt, read observable state
        uint afterBalance = address(c).balance;
        uint afterDeposits = c.depositsCount();

        // General rule: when withdraw is invoked with msg.sender != owner (here msg.sender would be C), the internal call must fail or not transfer funds.
        // Because withdraw has onlyOwner modifier, a call where msg.sender != owner should revert and thus leave balance and depositsCount unchanged.
        // We assert that either the sendMoney attempt reverted, or if it did not revert then balance and depositsCount are unchanged.
        assert(sendMoneyReverted || (afterBalance == beforeBalance && afterDeposits == beforeDeposits));
    }

    // allow this contract to receive ETH when tests send funds to it
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: sendAmount to deposit into c via fallback, withdrawAmount to attempt internal withdraw
    function run(uint sendAmount, uint withdrawAmount, bytes calldata withdrawData) public payable {
        require(true);

        // If we want to deposit into C so it has balance to withdraw, sendAmount is used.
        if (sendAmount > 0) {
            require(address(this).balance >= sendAmount);
            // call C's fallback to increase depositsCount and transfer ether into C
            (bool ok, ) = address(c).call{value: sendAmount}(new bytes(0));
            ok; // ignore success/failure here; state will be observed later
        }

        // record observables before the privileged self-call
        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount();

        // Prepare calldata for withdraw(uint) if caller wants to pass custom bytes; otherwise encode withdrawAmount
        bytes memory data = withdrawData.length == 0 ? abi.encodeWithSelector(bytes4(keccak256("withdraw(uint256)")), withdrawAmount) : withdrawData;

        // Attempt: as owner (this contract is the deployer/owner), call sendMoney on c to make c call itself.
        bool sendMoneyReverted;
        try c.sendMoney(address(c), 0, data) {
            sendMoneyReverted = false;
        } catch {
            sendMoneyReverted = true;
        }

        // read observables after
        uint afterBalance = address(c).balance;
        uint afterDeposits = c.depositsCount();

        // General invariant: either the sendMoney reverted, or if it did not revert then C's balance did not decrease and depositsCount is unchanged.
        // This ensures internal self-invocation cannot bypass onlyOwner to withdraw funds.
        assert(sendMoneyReverted || (afterBalance >= beforeBalance && afterDeposits == beforeDeposits));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Params:
    // depositAmount - ether to send to C via low-level call to trigger fallback (may be 0)
    // callValue - value argument passed to sendMoney (must be covered by this contract's balance if used)
    // data - calldata passed through sendMoney to target (often encoding withdraw or other function)
    function run(uint depositAmount, uint callValue, bytes calldata data) public payable {
        require(true);

        // If depositAmount > 0, send Ether to c to increase its balance and trigger fallback (which increments depositsCount).
        if (depositAmount > 0) {
            require(address(this).balance >= depositAmount);
            (bool sent,) = address(c).call{value: depositAmount}(new bytes(0));
            sent; // ignore success here; observation is read below
        }

        // Read observables before the privileged cross-call
        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount();

        // Attempt the privileged sendMoney call as the owner (this contract is the deployer/owner of c)
        // Must be a top-level state-changing call on c
        bool sendMoneyReverted;
        try c.sendMoney(address(c), callValue, data) {
            sendMoneyReverted = false;
        } catch {
            sendMoneyReverted = true;
        }

        // Read observables after
        uint afterBalance = address(c).balance;
        uint afterDeposits = c.depositsCount();

        // Assertion: if the sendMoney did not revert, then C's balance did not decrease and depositsCount did not decrease.
        // This captures that a successful self-call cannot withdraw funds or undo recorded deposits.
        assert(sendMoneyReverted || (afterBalance >= beforeBalance && afterDeposits >= beforeDeposits));
    }

    receive() external payable {}
}

