contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run will try to invoke withdraw or withdrawAll from this contract (which is NOT the owner of c)
    // Parameters:
    //  - callWithdrawAll: if true, call withdrawAll(), otherwise call withdraw(amount)
    //  - amount: value passed to withdraw when callWithdrawAll is false
    //  - sendToC: amount of Ether to send to c via fallback (to create some balance and increment depositsCount)
    function run(bool callWithdrawAll, uint amount, uint sendToC) public payable {
        require(true);
        // Ensure this test contract has enough balance to fund sending to c if requested
        if (sendToC > 0) {
            require(address(this).balance >= sendToC);
            // sendEther to c via low-level call to trigger fallback which increments depositsCount
            (bool ok,) = address(c).call{value: sendToC}("x");
            // the fallback in C is payable and does not revert, so ok should be true
            // but we do not assume that in the assert; we only proceed regardless
            ok; // silence unused warning
        }

        // Record observable state before the action
        uint beforeDeposits = c.depositsCount();
        uint beforeBalanceC = address(c).balance;
        uint beforeBalanceThis = address(this).balance;

        bool reverted;
        // Attempt the owner-only operations from this contract (which is not the owner of c)
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // If the test intended to call withdraw instead, redo using withdraw(amount)
        if (!callWithdrawAll) {
            // We already attempted withdrawAll above; to ensure single decision point, call withdraw(amount) now
            // Record state again before withdraw call
            beforeDeposits = c.depositsCount();
            beforeBalanceC = address(c).balance;
            beforeBalanceThis = address(this).balance;

            bool revoked2;
            try c.withdraw(amount) {
                revoked2 = false;
                reverted = false;
            } catch {
                revoked2 = true;
                reverted = true;
            }
            revoked2; // silence unused warning
        }

        // After attempted owner-only call, read observable state
        uint afterDeposits = c.depositsCount();
        uint afterBalanceC = address(c).balance;
        uint afterBalanceThis = address(this).balance;

        // Assert general rule: because this contract is not the owner of c (owner is deployer of c), any attempt
        // to call owner-only withdraw or withdrawAll from here must either revert, and if it reverts then
        // c's observable state (depositsCount and address(c).balance) must be unchanged. If it did not revert
        // (which would indicate this contract is owner), then balances may change — we express the rule as implication.
        assert(reverted ? (afterDeposits == beforeDeposits && afterBalanceC == beforeBalanceC && afterBalanceThis == beforeBalanceThis) : true);
    }

    // allow receiving Ether
    receive() external payable {}
}

