            && (reverted ? (afterDeposits == beforeDeposits && afterBalanceC == beforeBalanceC && afterBalanceThis == beforeBalanceThis)
                          : (
                                // succeeded: deposits unchanged and c's balance did not increase
                                afterDeposits == beforeDeposits && afterBalanceC <= beforeBalanceC
                            ))
        );
    }

