    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params:
    // callWithdrawAll: true => call withdrawAll(), false => call withdraw(amount)
    // amount: value to pass to withdraw when callWithdrawAll == false
    // sendToC: Ether to send to c before tested call (to populate balance)
    function run(bool callWithdrawAll, uint amount, uint sendToC) public payable {
        require(true);
        // If sending Ether to c, ensure this contract has enough balance
        if (sendToC > 0) {
            require(address(this).balance >= sendToC);
            // send Ether to c via a direct call to its fallback (counts as state-changing call on c)
            (bool ok,) = address(c).call{value: sendToC}("x");
            // we don't assert on this send; it's setup
            ok; 
        }

        // Observe before-state
        uint beforeDeposits = c.depositsCount();
        uint beforeBalanceC = address(c).balance;
        uint beforeBalanceThis = address(this).balance;

        // Perform exactly one tested call as a top-level statement
        bool reverted;
        if (callWithdrawAll) {
            try c.withdrawAll() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.withdraw(amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // Observe after-state
        uint afterDeposits = c.depositsCount();
        uint afterBalanceC = address(c).balance;
        uint afterBalanceThis = address(this).balance;

        // General rule:
        // - depositsCount never increases because of withdraw/withdrawAll (fallback only increments it),
        //   so afterDeposits >= beforeDeposits must hold in general; and withdraw* must not increase depositsCount.
        // - If the call reverted, balances and depositsCount remain unchanged.
        // - If the call succeeded, depositsCount must be equal to before, and c's balance must not have increased.
        assert(
