    // fundC: amount of wei to send to c before the tested call (to ensure c has balance)
    function run(bool callWithdrawAll, uint amount, uint fundC) public payable {
        require(true);
        // If funding c, ensure this contract has enough balance
        if (fundC > 0) {
            require(address(this).balance >= fundC);
            // top-level state-changing call to c: trigger fallback by sending data (empty data also triggers fallback)
            (bool okSend,) = address(c).call{value: fundC}("x");
            okSend; // ignore success here; it's setup
        }

        // Observe before-state via public getters
        uint beforeDeposits = c.depositsCount();
        uint beforeBalanceC = address(c).balance;
        uint beforeBalanceThis = address(this).balance;

        // Perform exactly one tested call as a top-level statement
        bool reverted;
        if (callWithdrawAll) {
            try c.withdrawAll() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.withdraw(amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // Observe after-state
        uint afterDeposits = c.depositsCount();
        uint afterBalanceC = address(c).balance;
        uint afterBalanceThis = address(this).balance;

        // General invariant:
        // - depositsCount must not increase as a result of withdraw/withdrawAll (fallback increments it, withdraws do not).
        // - If the call reverted, none of the observable state (depositsCount and balances) changed.
        // - If the call succeeded, depositsCount unchanged, c.balance did not increase, and test balance did not decrease.
        assert(
