                    afterDeposits == beforeDeposits && afterBalanceC == beforeBalanceC && afterBalanceThis == beforeBalanceThis
                ) : (
                    // succeeded => deposits unchanged and c.balance not increased and this contract didn't lose balance
                    afterDeposits == beforeDeposits && afterBalanceC <= beforeBalanceC && afterBalanceThis >= beforeBalanceThis
                ))
        );
    }

