    // Parameters:
    // amount: the value to withdraw (for withdraw) or ignored for withdrawAll
    // useWithdrawAll: if true call withdrawAll(), otherwise call withdraw(amount)
    function run(uint amount, bool useWithdrawAll) public payable {
        require(true);

        // Ensure this contract has enough balance to interact if needed (not strictly required for withdraw),
        // but keep to specification: do not read msg.value. The harness provides Ether to this contract if needed.
        // Record balances before the call.
        uint beforeC = address(c).balance;
        uint beforeMe = address(this).balance;

        bool reverted;
        // Perform the chosen call and catch reverts
        if (useWithdrawAll) {
            try c.withdrawAll() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.withdraw(amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        uint afterC = address(c).balance;
        uint afterMe = address(this).balance;

        // General rule:
        // - If the call reverted: neither contract balance nor this contract balance changed.
        // - If the call succeeded and withdraw(amount) was used: c's balance decreased by amount and this contract's balance increased by amount (unless amount > beforeC, in which case behavior depends on transfer and may revert; but here success implies amount <= beforeC).
        // - If the call succeeded and withdrawAll() was used: c's balance decreased by exactly (beforeC - afterC) and this contract's balance increased by that same amount.
        // We express these as a single assert using observable values and the reverted flag.

        assert(
            reverted ? (afterC == beforeC && afterMe == beforeMe)
            : (
                (!useWithdrawAll && afterC + amount == beforeC && afterMe == beforeMe + amount)
                || (useWithdrawAll && (beforeC - afterC == afterMe - beforeMe))
            )
        );
    }

    receive() external payable { }
}

