contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will test that owner-invoked withdraw and sendMoney either succeed and move Ether
    // from c to this contract (increasing address(this).balance) or revert; and that depositsCount
    // only increases when fallback is triggered by sending Ether to c.

    // Single public test function with inputs: amount to deposit to c via fallback, amount to withdraw,
    // target for sendMoney call (we will use address(this) to receive funds), and data payload.
    function run(uint depositAmount, uint withdrawAmount, uint sendAmount, address sendTarget, bytes calldata sendData) public payable {
        require(address(this).balance >= depositAmount + sendAmount, "insufficient test balance");
        // initial observations
        uint beforeCBalance = address(c).balance;
        uint beforeThisBalance = address(this).balance;
        uint beforeDeposits = c.depositsCount();

        // 1) trigger fallback by sending Ether to c (this will increment depositsCount on success)
        // Use call so fallback is invoked. We must ensure enough balance in this contract.
        (bool sentToC,) = address(c).call{value: depositAmount}(new bytes(0));
        // record after attempting deposit
        uint midCBalance = address(c).balance;
        uint midThisBalance = address(this).balance;
        uint midDeposits = c.depositsCount();

        // 2) Attempt owner withdraw of withdrawAmount
        bool withdrewReverted;
        try c.withdraw{gas: gasleft()}(withdrawAmount) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }
        uint afterWithdrawCBalance = address(c).balance;
        uint afterWithdrawThisBalance = address(this).balance;

        // 3) Attempt owner sendMoney to sendTarget with sendAmount and data
        bool sendReverted;
        try c.sendMoney{gas: gasleft()}(sendTarget, sendAmount, sendData) {
            sendReverted = false;
        } catch {
            sendReverted = true;
        }
        uint finalCBalance = address(c).balance;
        uint finalThisBalance = address(this).balance;
        uint finalDeposits = c.depositsCount();

        // General rule asserted:
        // - depositsCount increases by exactly 1 iff the deposit call succeeded and c's balance increased by depositAmount
        // - withdraw, if it did not revert, must decrease c's balance by withdrawAmount and increase this contract's balance by withdrawAmount
        // - sendMoney, if it did not revert and the target is this contract, must transfer sendAmount from c to this contract
        // We combine these into one conjunctive assertion over observed values and revert flags.
        assert(
            // depositsCount change matches success and balance change for the deposit attempt
            ( (sentToC && (midDeposits == beforeDeposits + 1) && (midCBalance == beforeCBalance + depositAmount) && (midThisBalance == beforeThisBalance - depositAmount))
              || (!sentToC && (midDeposits == beforeDeposits) && (midCBalance == beforeCBalance) && (midThisBalance == beforeThisBalance)) )
            // withdraw behavior: if not reverted, balances changed by withdrawAmount; if reverted, balances unchanged
            && ( (withdrewReverted && afterWithdrawCBalance == midCBalance && afterWithdrawThisBalance == midThisBalance)
                 || (!withdrewReverted && afterWithdrawCBalance + withdrawAmount == midCBalance && afterWithdrawThisBalance == midThisBalance + withdrawAmount) )
            // sendMoney behavior: if not reverted and target is this contract, balances reflect transfer; if reverted, balances unchanged
            && ( (sendReverted && finalCBalance == afterWithdrawCBalance && finalThisBalance == afterWithdrawThisBalance && finalDeposits == midDeposits)
                 || (!sendReverted && sendTarget == address(this) && finalCBalance + sendAmount == afterWithdrawCBalance && finalThisBalance == afterWithdrawThisBalance + sendAmount)
                 || (!sendReverted && sendTarget != address(this) && finalCBalance == afterWithdrawCBalance && finalThisBalance == afterWithdrawThisBalance)
               )
        );
    }

    // Allow receiving Ether when sendMoney targets this contract
    receive() external payable {}
}

