contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run attempts a withdraw by caller (the test contract) of amount 'amt' after optionally sending 'funds' to c via fallback.
    // We use two parameters: funds to send into c (to create balance) and amt to try to withdraw.
    // The test asserts that if this contract is not the owner of c, then withdraw must revert and c's balance and depositsCount remain unchanged;
    // if this contract is the owner, withdraw must succeed and reduce c's balance by amt (clamped by available balance via transfer semantics).
    function run(uint funds, uint amt) public payable {
        require(address(this).balance >= funds, "insufficient balance to fund");

        // Record before values
        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount();

        // If funds > 0, send Ether to c to trigger fallback (increasing depositsCount)
        if (funds > 0) {
            // must ensure this contract holds enough
            // send to c's address which will hit fallback and increment depositsCount
            (bool s,) = address(c).call{value: funds}("0x");
            // require the funding call succeeded for setting up the scenario
            require(s, "funding failed");
        }

        // Read after funding, before withdraw
        uint midBalance = address(c).balance;
        uint midDeposits = c.depositsCount();

        // Attempt withdraw and capture whether it reverted
        bool reverted;
        try c.withdraw(amt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after withdraw attempt
        uint afterBalance = address(c).balance;
        uint afterDeposits = c.depositsCount();

        // Determine if this contract is owner by comparing owner getter to address(this)
        bool amOwner = (c.owner() == address(this));

        // General rule:
        // - If caller is owner: call must not revert, and contract balance decreases by at most amt (i.e., afterBalance = midBalance - min(amt, midBalance))
        // - If caller is not owner: call must revert, and contract balance and depositsCount do not change from mid values
        if (amOwner) {
            // If owner, withdraw should not revert
            assert(reverted == false);
            // Compute expected after balance: cannot underflow; transfer sends up to amt but limited by midBalance
            // So afterBalance must be either midBalance (if amt==0) or midBalance - x where x <= amt and x <= midBalance.
            // We express this by checking afterBalance <= midBalance and midBalance - afterBalance <= amt && midBalance - afterBalance <= midBalance
            assert(afterBalance <= midBalance);
            uint withdrawn = midBalance - afterBalance;
            assert(withdrawn <= amt);
            assert(withdrawn <= midBalance);
            // depositsCount must not be changed by withdraws
            assert(afterDeposits == midDeposits);
        } else {
            // Not owner: withdraw must revert
            assert(reverted == true);
            // No state change allowed: balance and depositsCount unchanged from mid values
            assert(afterBalance == midBalance);
            assert(afterDeposits == midDeposits);
        }
    }

    // Allow receiving Ether so this contract can fund c
    receive() external payable {}
}

