            (afterBalanceC_send == beforeBalanceC2 && afterDeposits_send == beforeDeposits2) :
            (beforeBalanceC2 >= afterBalanceC_send && beforeBalanceC2 - afterBalanceC_send <= amount && afterDeposits_send == beforeDeposits2);

