            (afterBalanceC_withdrawAll == beforeBalanceC3 && afterDeposits_withdrawAll == beforeDeposits3) :
            (beforeBalanceC3 >= afterBalanceC_withdrawAll && beforeBalanceC3 - afterBalanceC_withdrawAll <= beforeBalanceC3 && afterDeposits_withdrawAll == beforeDeposits3);

        assert(withdraw_ok && send_ok && withdrawAll_ok);
    }

