        uint afterBal = address(c).balance;

        // general rule: if the call succeeded then depositsCount increased by 1 and balance increased by amount;
        // otherwise no change
        assert(ok ? (afterCount == beforeCount + 1 && afterBal == beforeBal + amount) : (afterCount == beforeCount && afterBal == beforeBal));
