contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // callAmount is the Ether to send with the empty-calldata call to trigger fallback
    function run(uint callAmount) public payable {
        require(address(this).balance >= callAmount);
        // read before-values
        uint beforeCount = c.depositsCount();
        uint beforeBal = address(c).balance;
        // perform the call to C with empty calldata via C's fallback by using a try on a low-level wrapper function pattern:
        // We must invoke a state-changing call on c as a top-level statement. Use a simple helper on C: there is no helper, but we can attempt to call a non-existent function will fail compile — so instead we use the fallback by calling c.sendMoney to a target of address(c) with data "" and value. However sendMoney exists and requires onlyOwner, and this contract is the deployer of c (the checker deploys fresh c with InvMutTest as msg.sender), so sendMoney can be used to forward value to c and trigger its fallback on the target. We'll call c.sendMoney(address(c), callAmount, "");
        bool didRevert;
        // top-level state-changing call
        try c.sendMoney(address(c), callAmount, "") {
            didRevert = false;
        } catch {
            didRevert = true;
        }
        // read after-values
        uint afterCount = c.depositsCount();
        uint afterBal = address(c).balance;
        // General rule: either the sendMoney call reverted and nothing changed, or it succeeded and the fallback executed increasing depositsCount by 1 and balance by callAmount.
        assert( (didRevert && afterCount == beforeCount && afterBal == beforeBal) || (!didRevert && afterCount == beforeCount + 1 && afterBal == beforeBal + callAmount) );
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // target: where to send, value: ether to send, data: calldata for the call
    function run(address target, uint value, bytes calldata data) public payable {
        // ensure this test contract has enough balance to forward 'value'
        require(address(this).balance >= value);
        // read before-values
        uint beforeCount = c.depositsCount();
        uint beforeBal = address(c).balance;
        bool didRevert;
        // top-level state-changing call: as deployer of c, this contract is owner and may call sendMoney
        try c.sendMoney(target, value, data) {
            didRevert = false;
        } catch {
            didRevert = true;
        }
        // read after-values
        uint afterCount = c.depositsCount();
        uint afterBal = address(c).balance;
        // General rule: if call reverted then nothing changed; if it succeeded then depositsCount unchanged and c.balance decreased by at most value (i.e., not increased)
        // We express "decreased by at most value" as: afterBal + 0 <= beforeBal && beforeBal - afterBal <= value  which simplifies to afterBal <= beforeBal && beforeBal - afterBal <= value
        assert( (didRevert && afterCount == beforeCount && afterBal == beforeBal) || (!didRevert && afterCount == beforeCount && afterBal <= beforeBal && beforeBal - afterBal <= value) );
    }
    receive() external payable { }
}

contract InvMutTest {
