    constructor(C _c) { c = _c; }
    // target: where to send, value: ether to send, data: calldata for the call
    function run(address target, uint value, bytes calldata data) public payable {
        require(address(this).balance >= value);
        uint beforeCount = c.depositsCount();
        uint beforeBal = address(c).balance;
        bool didRevert;
        // top-level state-changing call
        try c.sendMoney(target, value, data) {
            didRevert = false;
        } catch {
            didRevert = true;
        }
        uint afterCount = c.depositsCount();
        uint afterBal = address(c).balance;
        // single simple assertion: either reverted and nothing changed, or succeeded and depositsCount unchanged and balance did not drop by more than value
        assert((didRevert && afterCount == beforeCount && afterBal == beforeBal) || (!didRevert && afterCount == beforeCount && beforeBal >= afterBal && beforeBal - afterBal <= value));
    }
    receive() external payable { }
}
